parameters.jsCode:
function parseJson(value) {
  const text = String(value ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  return JSON.parse(text);
}
const proposed = parseJson($('Goal Specification Agent').item.json.output);
const response = String($json.chatInput ?? '').trim();
let approvedSpecification;
let approvalMode;
if (/^APPROVE$/i.test(response)) {
  approvedSpecification = proposed;
  approvalMode = 'approved-as-proposed';
} else {
  try {
    approvedSpecification = parseJson(response);
    approvalMode = 'user-modified-and-approved';
  } catch {
    throw new Error('Plan was not approved. Reply APPROVE or submit a complete modified JSON contract. Codex has not run.');
  }
}
const requiredString = ['goal', 'implementationTask', 'reviewerInstructions', 'verificationProfile'];
for (const key of requiredString) {
  if (typeof approvedSpecification[key] !== 'string' || !approvedSpecification[key].trim()) throw new Error(`Approved plan is missing ${key}.`);
}
if (!Array.isArray(approvedSpecification.constraints) || approvedSpecification.constraints.length === 0) throw new Error('Approved plan requires constraints.');
if (!Array.isArray(approvedSpecification.acceptanceCriteria) || approvedSpecification.acceptanceCriteria.length === 0) throw new Error('Approved plan requires acceptanceCriteria.');
if (approvedSpecification.verificationProfile !== 'agent-data-sidebar-targeted') throw new Error('verificationProfile must remain agent-data-sidebar-targeted because workflow commands are server-controlled.');
return [{ json: { approvedSpecification, approval: { mode: approvalMode, confirmedAt: new Date().toISOString() } } }];

const codex = $('Codex Coding Agent').item.json;
let reviewer;
try {
  const text = String($json.output ?? '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  reviewer = JSON.parse(text);
} catch {
  reviewer = { score: 0, verdict: 'blocked', summary: 'Reviewer did not return valid JSON.', issues: [{ id: 'review-json', severity: 'error', message: 'Reviewer output is unavailable or invalid.' }] };
}
return [{ json: { artifact: codex.artifact, checks: codex.checks, reviewer, extraContext: { codexRunId: codex.codexCoding.runId, threadId: codex.codexCoding.threadId, turnId: codex.codexCoding.turnId, summary: codex.codexCoding.summary, approvedSpecification: $('Finalize Approved Goal Plan').item.json.approvedSpecification } } }];

